# port scan plugin
yakit.AutoInitYakit()

CVEs = []
addCVE = func(cve, rules, score, severity, titleZh, titleEn) {
    if (str.Contains(rules, ",")) {
        rules = str.Join(x.Map(str.Split(rules, ","), func(i) {
            return sprintf(`(%v)`, str.ReplaceAll(str.TrimSpace(i), ".", `\.`))
        }), "|")
    }
    CVEs = append(CVEs, {
        "cve": cve,
        "rule": rules,
        "score": score,
        "severity": severity,
        "titleZh": titleZh,
        "titleEn": titleEn, 
    })
}

addCVE("CVE-2015-6942", "3.0","6.1", "MEDIUM", "Coremail XT3.0 Document Attachment 跨站点脚本漏洞", "Coremail XT3.0 Document Attachment XSS")
addCVE("CVE-2018-14503", "3.0","6.1", "MEDIUM", "Coremail XT 3.0 intervalCheck.jsp Parameter 跨站脚本攻击漏洞", "Coremail XT 3.0 intervalCheck.jsp Parameter XSS")
addCVE("CVE-2018-9330", "3.0","5.4", "MEDIUM", "Coremail XT 3.0 register.jsp 跨站脚本攻击漏洞", "Coremail XT 3.0 register.jsp XSS")
addCVE("CVE-2020-29133", "5.0","6.1", "MEDIUM", "coremail_xt_project coremail_xt 跨站脚本漏洞", "coremail_xt_project coremail_xt XSS")



handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen() {
        return
    }

    if result.Fingerprint == nil {
        return
    }
    if str.MatchAllOfRegexp(result.GetServiceName(),"(?i)Coremail|Coremail XT") {
    yakit.Info("cves: %d", len(CVEs))

        x.Foreach(CVEs, func(i) {
            defer func{
                err = recover()
                if err != nil {
                    yakit.Error("Coremail CVE 合规检查失败：%v", err)
                }
            }
            if !str.MatchAllOfRegexp(result.Fingerprint.Version, i.rule) {
                return
            }

            target := str.HostPort(result.Target, result.Port)
            targetOutput := sprintf("(%v)", target)
            risk.NewRisk(
                target, 
                risk.title(sprintf(`%v:%v%v`, i.cve, i["titleEn"], targetOutput)),
                risk.titleVerbose(sprintf(`%v:%v%v`, i.cve, i["titleZh"], targetOutput)),
                risk.type("cve-baseline"),
                risk.typeVerbose("CVE基线检查"),
                risk.parameter(result.Fingerprint.Banner),
                risk.potential(true),
                risk.level("low"),
                risk.details(i),
                risk.cve(i.cve),
            )
            println(i.cve)
        })
    }
}
